// Pre-runtime seccomp stage, approach (2b). Linked as the ELF entry point
// with -ldflags="-E main.prestart". Runs before _rt0_amd64_linux, i.e.
// before the Go runtime exists: no stack checks, no TLS, raw syscalls only.
// If argv[1] is "net" or "emu", it sets no_new_privs and installs preFprog
// (generated by cmd/genfilter), then jumps to the normal Go entry point with
// the stack exactly as the kernel left it.

#include "textflag.h"

TEXT ·prestart(SB),NOSPLIT|NOFRAME,$0
	MOVQ	0(SP), AX		// argc
	CMPQ	AX, $2
	JLT	done
	MOVQ	16(SP), SI		// argv[1]
	MOVL	0(SI), AX
	CMPL	AX, $0x0074656e		// "net\0"
	JEQ	install
	CMPL	AX, $0x00756d65		// "emu\0"
	JEQ	install
	JMP	done

install:
	// prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0)
	MOVQ	$157, AX
	MOVQ	$38, DI
	MOVQ	$1, SI
	XORQ	DX, DX
	XORQ	R10, R10
	XORQ	R8, R8
	SYSCALL
	CMPQ	AX, $0
	JNE	fail
	// seccomp(SECCOMP_SET_MODE_FILTER, 0, &preFprog)
	MOVQ	$317, AX
	MOVQ	$1, DI
	XORQ	SI, SI
	LEAQ	·preFprog(SB), DX
	SYSCALL
	CMPQ	AX, $0
	JNE	fail

done:
	XORQ	DX, DX			// rtld_fini: none (static binary)
	JMP	_rt0_amd64_linux(SB)

fail:
	// exit_group(111): refuse to run the role unconfined
	MOVQ	$231, AX
	MOVQ	$111, DI
	SYSCALL
